<?php
/**
 * Dependency + version manifest for editor.js.
 *
 * Normally generated by @wordpress/scripts. Because this plugin ships without a
 * build step, we declare the handles the editor script relies on by hand so
 * WordPress enqueues them before our script.
 *
 * @package ReviewsBlock
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

return array(
	'dependencies' => array(
		'wp-blocks',
		'wp-block-editor',
		'wp-components',
		'wp-element',
		'wp-i18n',
		'wp-server-side-render',
	),
	'version'      => '1.0.0',
);
